package com.bjjj.todo;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.time.*;import java.util.*;
public class Reminder extends BroadcastReceiver {
 static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,90,new Intent(c,Reminder.class).setAction("com.bjjj.todo.ALARM"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static NotificationManager manager(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("tasks","待办提醒",NotificationManager.IMPORTANCE_HIGH));return n;}
 static boolean allowed(Context c){NotificationManager n=manager(c);return n.areNotificationsEnabled()&&n.getNotificationChannel("tasks").getImportance()!=NotificationManager.IMPORTANCE_NONE;}
 public static synchronized void schedule(Context c){try{long now=System.currentTimeMillis(),next=LocalDate.now().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();if(allowed(c))for(JSONObject t:Store.open(Store.read(c))){long due=Store.due(t);JSONArray offsets=t.optJSONArray("offsets"),fired=t.optJSONArray("fired");if(offsets!=null&&due!=Long.MAX_VALUE)for(int j=0;j<offsets.length();j++){double offset=offsets.optDouble(j);if(!contains(fired,offset))next=Math.min(next,Math.max(now+1500,due-(long)(offset*60000)));}}AlarmManager a=c.getSystemService(AlarmManager.class);a.cancel(alarm(c));if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,alarm(c));else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,alarm(c));}catch(Exception e){android.util.Log.e("bjjj","Reminder scheduling failed",e);}}
 static boolean contains(JSONArray a,double value){if(a!=null)for(int i=0;i<a.length();i++)if(a.optDouble(i)==value)return true;return false;}
 public void onReceive(Context c,Intent intent){try{if(allowed(c)){synchronized(Store.class){JSONObject root=Store.read(c);boolean changed=false;for(JSONObject t:Store.open(root)){long due=Store.due(t);JSONArray offsets=t.optJSONArray("offsets"),fired=t.optJSONArray("fired");if(fired==null)fired=new JSONArray();boolean send=false;if(offsets!=null&&due!=Long.MAX_VALUE)for(int j=0;j<offsets.length();j++){double offset=offsets.optDouble(j);if(!contains(fired,offset)&&due-offset*60000<=System.currentTimeMillis()){fired.put(offset);send=true;}}if(send){manager(c).notify(t.optString("id").hashCode(),new Notification.Builder(c,"tasks").setSmallIcon(R.drawable.notification_icon).setContentTitle(t.optString("title")).setContentText("不急及及代办 · 打开应用查看截止时间").setContentIntent(TodoWidget.activity(c,false)).setAutoCancel(true).build());t.put("fired",fired);changed=true;}}if(changed)Store.write(c,root);}}TodoWidget.updateAll(c);schedule(c);}catch(Exception e){android.util.Log.e("bjjj","Reminder failed",e);}}
}
